import unreal,json,math
from pathlib import Path
root=Path(unreal.Paths.project_dir()).parents[1]
exec((root/'work/migrate_delivery_blueprints.py').read_text(encoding='utf-8-sig').split('reports=[]')[0])
reports=[]
for role in ['DeliveryRider','Cashier','Chef','TechClerk','Pharmacist','Florist','CustomerStudent','CustomerOffice','CustomerNeighbor']:
 bp=unreal.load_asset('/Game/Delivery/Animation/ABP_'+role);assert bp,role
 g=Graph();g.node('Motion','break',type='/Script/BogotaVoxel.DeliveryMotionInput');g.link('entry','Motion','Motion','DeliveryMotionInput')
 g.get('Walking');g.get('WalkRate')
 def inp(field,node,pin):g.link('Motion',field,node,pin)
 def mathnode(id,fn,**defaults):g.call(id,fn,M,**defaults)
 mathnode('RiderThreshold','SelectFloat',A='8',B='25');g.link('Walking','Walking','RiderThreshold','bPickA')
 mathnode('NPCThreshold','SelectFloat',A='3',B='8');g.link('Walking','Walking','NPCThreshold','bPickA')
 mathnode('Threshold','SelectFloat');g.link('RiderThreshold','ReturnValue','Threshold','A');g.link('NPCThreshold','ReturnValue','Threshold','B');inp('HasRider','Threshold','bPickA')
 mathnode('Moving','Greater_DoubleDouble');inp('Speed','Moving','A');g.link('Threshold','ReturnValue','Moving','B')
 g.setter('SetWalking','Walking','Moving');g.setter('SetMounted','Mounted','Motion','Riding');g.setter('SetMoto','Motorcycle','Motion','Moto')
 mathnode('Landing','Greater_DoubleDouble',B='0');inp('LandingTime','Landing','A')
 mathnode('AirOrLanding','BooleanOR');inp('Falling','AirOrLanding','A');g.link('Landing','ReturnValue','AirOrLanding','B')
 mathnode('OnFoot','Not_PreBool');inp('Riding','OnFoot','A');mathnode('Jump','BooleanAND');g.link('OnFoot','ReturnValue','Jump','A');g.link('AirOrLanding','ReturnValue','Jump','B')
 g.setter('SetJump','Jumping','Jump')
 mathnode('NPCRate','Divide_DoubleDouble',B='50');inp('Speed','NPCRate','A')
 mathnode('ClampNPCRate','FClamp',Min='.3',Max='1.6');g.link('NPCRate','ReturnValue','ClampNPCRate','Value')
 mathnode('TargetRate','SelectFloat');inp('TargetWalkRate','TargetRate','A');g.link('ClampNPCRate','ReturnValue','TargetRate','B');inp('HasRider','TargetRate','bPickA')
 mathnode('SmoothRate','FInterpTo');g.link('WalkRate','WalkRate','SmoothRate','Current');g.link('TargetRate','ReturnValue','SmoothRate','Target');g.link('entry','Dt','SmoothRate','DeltaTime');inp('WalkResponse','SmoothRate','InterpSpeed')
 g.setter('SetRate','WalkRate','SmoothRate')
 mathnode('PedalRevolutions','Divide_DoubleDouble',B=str(2*math.pi));inp('CrankAngle','PedalRevolutions','A')
 mathnode('Cycle','Percent_FloatFloat',B='1');g.link('PedalRevolutions','ReturnValue','Cycle','A')
 mathnode('PedalSeconds','Multiply_DoubleDouble');g.link('Cycle','ReturnValue','PedalSeconds','A');inp('PedalLength','PedalSeconds','B');g.setter('SetPedal','PedalTime','PedalSeconds')
 mathnode('AirDelta','Subtract_DoubleDouble');inp('JumpVelocity','AirDelta','A');inp('VerticalSpeed','AirDelta','B')
 mathnode('AirRange','Multiply_DoubleDouble',B='2');inp('JumpVelocity','AirRange','A')
 mathnode('SafeAirRange','FMax',B='.001');g.link('AirRange','ReturnValue','SafeAirRange','A')
 mathnode('AirFraction','Divide_DoubleDouble');g.link('AirDelta','ReturnValue','AirFraction','A');g.link('SafeAirRange','ReturnValue','AirFraction','B')
 mathnode('ClampAir','FClamp',Min='0',Max='1');g.link('AirFraction','ReturnValue','ClampAir','Value')
 mathnode('AirPhase','Lerp',A='.3',B='.7');g.link('ClampAir','ReturnValue','AirPhase','Alpha')
 mathnode('LandingFraction','Divide_DoubleDouble',B='.18');inp('LandingTime','LandingFraction','A')
 mathnode('LandingElapsed','Subtract_DoubleDouble',A='1');g.link('LandingFraction','ReturnValue','LandingElapsed','B')
 mathnode('ClampLanding','FClamp',Min='0',Max='1');g.link('LandingElapsed','ReturnValue','ClampLanding','Value')
 mathnode('LandingPhase','Lerp',A='.7',B='1');g.link('ClampLanding','ReturnValue','LandingPhase','Alpha')
 mathnode('JumpPhase','SelectFloat');g.link('AirPhase','ReturnValue','JumpPhase','A');g.link('LandingPhase','ReturnValue','JumpPhase','B');inp('Falling','JumpPhase','bPickA')
 mathnode('JumpSeconds','Multiply_DoubleDouble');g.link('JumpPhase','ReturnValue','JumpSeconds','A');inp('JumpLength','JumpSeconds','B');g.setter('SetJumpTime','JumpTime','JumpSeconds')
 chain=['entry','SetWalking','SetMounted','SetMoto','SetJump','SetRate','SetPedal','SetJumpTime','result']
 for a,b in zip(chain,chain[1:]):g.exec(a,b)
 report=g.build('UpdateMotion');report['blueprint']=bp.get_path_name();reports.append(report)
 assert unreal.EditorAssetLibrary.save_loaded_asset(bp,only_if_is_dirty=False)
out=Path(unreal.Paths.project_saved_dir(),'blueprint_migration.json');data=json.loads(out.read_text());data['animation_motion_graphs']=reports;out.write_text(json.dumps(data,indent=2))
unreal.log('ANIMATION_MOTION_BLUEPRINTS_SAVED '+json.dumps(reports))
